import time
import numpy as np
import scipy.linalg as sla
np.random.seed(0)

# fixed pseudo-random RHS (module level, avoids RNG per call)
_Y = (np.arange(1,11).astype(complex) * 0.61803398875 + 1j*np.arange(1,11).astype(complex)*0.38196601125)
EYECACHE={}
def I(n):
    if n not in EYECACHE: EYECACHE[n]=np.eye(n)
    return EYECACHE[n]
def yc(n):
    return _Y[:n].copy()

def ref(A):
    w,v=np.linalg.eig(A); i=int(np.argmax(np.abs(w))); return w[i],v[:,i]

def cand_solve(A):
    w=np.linalg.eigvals(A); lam=w[int(np.argmax(np.abs(w)))]
    x=np.linalg.solve(A-lam*I(A.shape[0]), yc(A.shape[0]))
    return lam,x

def cand_norm(A):
    w=np.linalg.eigvals(A); lam=w[int(np.argmax(np.abs(w)))]
    x=np.linalg.solve(A-lam*I(A.shape[0]), yc(A.shape[0]))
    x/=np.linalg.norm(x); return lam,x

def cand_scipy(A):
    w,v=sla.eig(A); i=int(np.argmax(np.abs(w))); return w[i],v[:,i]

cands={'ref':ref,'solve1':cand_solve,'solve1norm':cand_norm,'scipy_eig':cand_scipy}
for size in [2,4,6,8,10]:
    N=100
    res={k:[] for k in cands}
    for i in range(N):
        A=np.random.normal(size=(size,size)).astype(np.float64)
        for k,f in cands.items():
            t0=time.perf_counter(); f(A); t1=time.perf_counter(); res[k].append(t1-t0)
    line=f"{size}x{size}: "
    for k in cands:
        line+=f"{k}={np.median(res[k])*1e6:6.1f}us  "
    print(line)

# correctness of cand_solve across all sizes
print("\ncorrectness (allclose A@v==lam v):")
for size in range(2,11):
    bad=0; maxres=0
    for _ in range(300):
        A=np.random.normal(size=(size,size)).astype(np.float64)
        lam,v=cand_solve(A)
        r=np.linalg.norm(A@v-lam*v)/np.linalg.norm(v); maxres=max(maxres,r)
        if not np.allclose(A@v,lam*v): bad+=1
    print(f"  size {size}: fail {bad}/300 maxrelres {maxres:.2e}")
