import time
import numpy as np
import scipy.linalg as sla
np.random.seed(0)
_Y=[ (i+1)*0.61803398875 + 1j*(i+1)*0.38196601125 for i in range(10)]
Y=np.array(_Y,dtype=complex)
def I(n): return np.eye(n)

# candidate pipelines
def ref(A):
    w,v=np.linalg.eig(A); i=int(np.argmax(np.abs(w))); return w[i],v[:,i]
def p1_sci(A):
    w=np.linalg.eigvals(A); lam=w[int(np.argmax(np.abs(w)))]
    M=A-lam*I(A.shape[0]); M=M.astype(complex)
    x=sla.solve(M, Y[:M.shape[0]], check_finite=False, overwrite_a=True)
    return lam,x
def p2_lu(A):
    w=np.linalg.eigvals(A); lam=w[int(np.argmax(np.abs(w)))]
    M=(A-lam*I(A.shape[0])).astype(complex)
    lu=sla.lu_factor(M, overwrite_a=True); x=sla.lu_solve(lu, Y[:M.shape[0]])
    return lam,x
def p3_2step(A):
    w=np.linalg.eigvals(A); lam=w[int(np.argmax(np.abs(w)))]
    M=(A-lam*I(A.shape[0])).astype(complex)
    lu=sla.lu_factor(M, overwrite_a=True); x=sla.lu_solve(lu, Y[:M.shape[0]])
    x/=np.linalg.norm(x); x=sla.lu_solve(lu,x); return lam,x

print("=== speed (fresh matrices, interleaved, median) ===")
for size in [2,4,6,8,10]:
    N=150; r={k:[] for k in ['ref','p1_sci','p2_lu','p3_2']}
    fs={'ref':ref,'p1_sci':p1_sci,'p2_lu':p2_lu,'p3_2':p3_2step}
    for i in range(N):
        A=np.random.normal(size=(size,size)).astype(np.float64)
        for k in r:
            t0=time.perf_counter(); fs[k](A); t1=time.perf_counter(); r[k].append(t1-t0)
    print(f"{size}x{size}: " + "  ".join(f"{k}={np.median(r[k])*1e6:6.1f}" for k in r))

print("\n=== robustness: allclose fail / solve-raise count (400 mats each size) ===")
for size in [2,3,4,5,6,7,8,9,10]:
    stats={'p1':(0,0,0.0),'p2':(0,0,0.0),'p3':(0,0,0.0)}
    for _ in range(400):
        A=np.random.normal(size=(size,size)).astype(np.float64)
        for name,fn in [('p1',p1_sci),('p2',p2_lu),('p3',p3_2step)]:
            try:
                lam,v=fn(A)
                rr=np.linalg.norm(A@v-lam*v)/np.linalg.norm(v); stats[name][2]=max(stats[name][2],rr)
                if not np.allclose(A@v,lam*v): stats[name][0]+=1
            except Exception as e:
                stats[name][1]+=1
    for name in ['p1','p2','p3']:
        print(f"  {size}x{size} {name}: allclose_fail={stats[name][0]}/400 raise={stats[name][1]}/400 maxrelres={stats[name][2]:.1e}")
